//! Files on the data volume (product pictures, later attachments). Names are
//! generated by Vorrat, and only names of that shape are ever served or stored,
//! so a request can't reach outside the folder.

use std::path::Path;

use anyhow::Result;

/// `img-<32 hex>.jpg|png|webp` or `att-<32 hex>.<ext>`.
pub fn is_safe_name(name: &str) -> bool {
    let Some((stem, ext)) = name.rsplit_once('.') else {
        return false;
    };
    let Some(hex) = stem
        .strip_prefix("img-")
        .or_else(|| stem.strip_prefix("att-"))
    else {
        return false;
    };
    hex.len() == 32
        && hex.bytes().all(|b| b.is_ascii_hexdigit())
        && !ext.is_empty()
        && ext.len() <= 5
        && ext.bytes().all(|b| b.is_ascii_alphanumeric())
}

pub fn new_name(prefix: &str, ext: &str) -> String {
    format!("{prefix}-{}.{ext}", random_hex(16))
}

/// `bytes` random bytes as lowercase hex.
pub fn random_hex(bytes: usize) -> String {
    let mut b = vec![0u8; bytes];
    getrandom(&mut b);
    b.iter().map(|x| format!("{x:02x}")).collect()
}

/// Random bytes from the OS.
fn getrandom(buf: &mut [u8]) {
    use std::io::Read;
    if let Ok(mut f) = std::fs::File::open("/dev/urandom") {
        if f.read_exact(buf).is_ok() {
            return;
        }
    }
    // Fallback (non-Unix): time + address entropy; names only need to be unique.
    let seed = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0)
        ^ (buf.as_ptr() as u128);
    for (i, b) in buf.iter_mut().enumerate() {
        *b = (seed >> ((i % 16) * 8)) as u8 ^ (i as u8).wrapping_mul(151);
    }
}

pub fn content_type(name: &str) -> &'static str {
    match name
        .rsplit_once('.')
        .map(|(_, e)| e.to_ascii_lowercase())
        .as_deref()
    {
        Some("png") => "image/png",
        Some("webp") => "image/webp",
        Some("jpg" | "jpeg") => "image/jpeg",
        Some("pdf") => "application/pdf",
        _ => "application/octet-stream",
    }
}

pub fn write(dir: &Path, name: &str, bytes: &[u8]) -> Result<()> {
    std::fs::create_dir_all(dir)?;
    let tmp = dir.join(format!(".{name}.tmp"));
    std::fs::write(&tmp, bytes)?;
    std::fs::rename(tmp, dir.join(name))?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn only_generated_names_are_safe() {
        let n = new_name("img", "jpg");
        assert!(is_safe_name(&n), "{n}");
        assert_ne!(n, new_name("img", "jpg"));
        for bad in [
            "../vorrat.db",
            "img-../../etc/passwd",
            "vorrat.db",
            "img-zz.jpg",
            "img-0123456789abcdef0123456789abcdef.j/g",
            "",
        ] {
            assert!(!is_safe_name(bad), "{bad}");
        }
    }
}
